/**
     * Copies a stream into the normalized archive in bounded chunks, checking
     * the cancellation flag every chunk so a large embedded override file
     * (e.g. a whole world or resource pack inside the client archive) can be
     * aborted mid-copy instead of blocking a Cancel request until the file
     * finishes copying.
     */
    private function copyStreamWithCancellation(
        $source,
        $destination,
        string $label,
    ): void {
        while (!feof($source)) {
            if ($this->downloader->isCancelled()) {
                throw new InstallationCancelledException(
                    'Installation cancelled.'
                );
            }

            $chunk = fread($source, 262144);

            if ($chunk === false) {
                throw new RuntimeException(
                    'Unable to read a modpack file: ' . $label
                );
            }

            if ($chunk === '') {
                if (feof($source)) {
                    break;
                }

                continue;
            }

            $written = fwrite($destination, $chunk);

            if ($written === false || $written !== strlen($chunk)) {
                throw new RuntimeException(
                    'Unable to copy a modpack file into the normalized archive: ' . $label
                );
            }
        }
    }

    private function manifestOverridesPath(array $manifest): string

