private function buildServerArchive(
    ZipArchive $source,
    string $archivePath,
    array $manifest,
): string {
    $content = $this->collectArchiveContent(
        $source,
        $this->manifestOverridesPath($manifest),
    );

    [$installedMods, $wantedMods] = $this->mergeManifestFiles($manifest, $content);

    if ($content === []) { throw ...; }
    if ($wantedMods > 0 && $installedMods === 0) { throw ...; }

    $archiveBytes = max(0, (int) @filesize($archivePath));
    foreach ($content as $payload) {
        if ($payload['archiveEntry'] === null) {
            $archiveBytes += max(0, (int) $payload['bytes']);
        }
    }

    $networkBytesDone = max(0, (int) @filesize($archivePath));

    $this->downloader->setProgressOffset($networkBytesDone, max($networkBytesDone, $archiveBytes));

    $root = rtrim($this->temporaryRoot, DIRECTORY_SEPARATOR);
    if (!is_dir($root) && !mkdir($root, 0750, true) && !is_dir($root)) {
        throw new RuntimeException('Unable to create the temporary package directory.');
    }

    $outputPath = $root . '/' . bin2hex(random_bytes(16)) . '.zip';

    $output = @fopen($outputPath, 'wb+');
    if ($output === false) {
        throw new RuntimeException('Unable to create the normalized package archive.');
    }

    $centralDirectory = [];
    $downloadedTemps = [];
    $downloadedMods = 0;

    try {
        foreach ($content as $relative => $payload) {
            if ($this->downloader->isCancelled()) {
                throw new InstallationCancelledException('Installation cancelled.');
            }

            $stream = null;

            try {
                if ($payload['archiveEntry'] !== null) {
                    $stream = $source->getStream($payload['archiveEntry']);
                    if ($stream === false) {
                        throw new RuntimeException('Unable to read an entry from the modpack archive.');
                    }
                    $baseDone = $networkBytesDone;
                } else {
                    $downloadPath = $this->downloadBestUrl($payload['downloadUrls'], $networkBytesDone, $archiveBytes);
                    if ($downloadPath === null) {
                        continue;
                    }
                    $downloadedMods++;
                    $downloadedTemps[] = $downloadPath;
                    $networkBytesDone += max(0, (int) $payload['bytes']);
                    $stream = @fopen($downloadPath, 'rb');
                    if ($stream === false) {
                        throw new RuntimeException('Unable to read a downloaded modpack file.');
                    }
                    $baseDone = $networkBytesDone;
                }

                $centralDirectory[] = $this->writeArchiveEntry($output, $stream, $relative, $baseDone, $archiveBytes);
            } finally {
                if ($stream !== null) {
                    fclose($stream);
                }
            }
        }

        if ($wantedMods > 0 && $downloadedMods === 0) {
            throw new UnsupportedModpackPackageException('...');
        }

        $this->finishArchive($outputPath, $output, $centralDirectory);
    } finally {
        fclose($output);
        foreach ($downloadedTemps as $downloadPath) {
            @unlink($downloadPath);
        }
    }

    return $outputPath;
}
```

