/**
     * Streams one file into the normalized archive as an uncompressed (STORED)
     * zip member. Bytes are written straight from the source stream so the
     * archive is produced in a single pass: the cancellation flag is consulted
     * and cumulative progress reported every chunk. No deferred
     * "deflate everything on close" step remains that could swallow a Cancel
     * request for the life of a large archive rewrite.
     *
     * The final CRC and sizes are unknown until the stream is consumed, so a
     * placeholder local header is written first and its CRC/size fields are
     * patched once the entry has finished streaming (the output handle is
     * seekable).
     *
     * @param resource $output
     * @param resource $stream
     *
     * @return array{name: string, crc: int, size: int, offset: int, dosTime: int}
     */
    private function writeArchiveEntry(
        $output,
        $stream,
        string $relative,
        int $baseDone,
        int $archiveBytes,
    ): array {
        $offset = (int) ftell($output);
        $nameLength = strlen($relative);
        $dosTime = $this->dosDateTime();

        $this->writeLocalHeader($output, $relative, $nameLength, $dosTime);

        $crcHash = hash_init('crc32b');
        $size = 0;

        while (!feof($stream)) {
            if ($this->downloader->isCancelled()) {
                throw new InstallationCancelledException(
                    'Installation cancelled.'
                );
            }

            $chunk = fread($stream, 262144);

            if ($chunk === false) {
                throw new RuntimeException(
                    'Unable to read a modpack file: ' . $relative
                );
            }

            if ($chunk === '') {
                if (feof($stream)) {
                    break;
                }

                continue;
            }

            $written = fwrite($output, $chunk);

            if ($written === false || $written !== strlen($chunk)) {
                throw new RuntimeException(
                    'Unable to write a modpack file into the normalized archive: ' . $relative
                );
            }

            hash_update($crcHash, $chunk);

            $size += strlen($chunk);

            $this->downloader->reportProgress(
                $baseDone + $size,
                $archiveBytes,
            );
        }

        if ($size > 0xFFFFFFFF) {
            throw new RuntimeException(
                'A modpack file in the normalized archive exceeds the maximum supported size.',
            );
        }

        $crc = unpack('V', hash_final($crcHash, true))[1];

        // Patch the placeholder header with the real CRC and sizes.
        fseek($output, $offset + 14, SEEK_SET);
        fwrite($output, pack('V', $crc));
        fwrite($output, pack('V', $size));
        fwrite($output, pack('V', $size));
        fseek($output, 0, SEEK_END);

        return [
            'name' => $relative,
            'crc' => $crc,
            'size' => $size,
            'offset' => $offset,
            'dosTime' => $dosTime,
        ];
    }

    /**
     * Writes a STORED local file header with placeholder (zeroed) CRC and
     * sizes; the entry content follows and writeArchiveEntry() patches the
     * real values afterwards.
     *
     * @param resource $output
     */
    private function writeLocalHeader(
        $output,
        string $name,
        int $nameLength,
        int $dosTime,
    ): void {
        fwrite($output, pack('VvvvvvVVVvv', 0x04034b50, 20, 0, 0, $dosTime & 0xFFFF, ($dosTime >> 16) & 0xFFFF, 0, 0, 0, $nameLength, 0));
        fwrite($output, $name);
    }

    /**
     * Finalizes the normalized archive by writing the central directory and
     * the end-of-central-directory record. All entry payloads were already
     * streamed during writeArchiveEntry(), so this step is bounded and fast.
     *
     * @param resource $output
     * @param array<int, array{name: string, crc: int, size: int, offset: int, dosTime: int}> $entries
     */
    private function finishArchive($output, array $entries): void
    {
        if (count($entries) > 0xFFFF) {
            throw new RuntimeException(
                'The normalized modpack archive contains too many files.',
            );
        }

        $centralDirectoryOffset = (int) ftell($output);

        foreach ($entries as $entry) {
            $nameLength = strlen($entry['name']);

            fwrite($output, pack('VvvvvvvVVVvvvvvVV', 0x02014b50, 20, 20, 0, 0, $entry['dosTime'] & 0xFFFF, ($entry['dosTime'] >> 16) & 0xFFFF, $entry['crc'], $entry['size'], $entry['size'], $nameLength, 0, 0, 0, 0, 0100644 << 16, $entry['offset']));
            fwrite($output, $entry['name']);
        }

        $centralDirectorySize = (int) ftell($output) - $centralDirectoryOffset;

        fwrite($output, pack('VvvvvVVv', 0x06054b50, 0, 0, count($entries), count($entries), $centralDirectorySize, $centralDirectoryOffset, 0));
    }

    /**
     * Encodes the current local time as a DOS date/time value for use in zip
     * entry headers.
     */
    private function dosDateTime(): int
    {
        $now = getdate();

        $date = (($now['year'] - 1980) << 9)
            | ($now['mon'] << 5)
            | $now['mday'];

        $time = ($now['hours'] << 11)
            | ($now['minutes'] << 5)
            | intdiv($now['seconds'], 2);

        return ($date << 16) | $time;
    }

