StoredZipWriter design:
```php
<?php

namespace Pterodactyl\BlueprintFramework\Extensions\modpackinstaller\Services\Archive;

use Pterodactyl\BlueprintFramework\Extensions\modpackinstaller\Services\Installation\InstallationCancelledException;
use RuntimeException;

/**
 * Produces a normalized STORED (uncompressed) zip archive by streaming each
 * entry directly into the destination. ... cancellation/progress callbacks per chunk, no deferred deflate.
 */
final class StoredZipWriter
{
    private array $centralDirectory = [];

    /**
     * @param resource $output
     */
    public function __construct(
        private $output,
        private readonly ?\Closure $cancelChecker = null,
        private readonly ?\Closure $progressCallback = null,
    ) {
    }

    public function addFileFromStream($stream, string $relative, int $baseDone = 0, ?int $totalBytes = null): void
    {
        $checker = $this->cancelChecker;
        if ($checker !== null && $checker()) {
            throw new InstallationCancelledException('Installation cancelled.');
        }

        $offset = (int) ftell($this->output);
        $nameLength = strlen($relative);
        $dosTime = $this->dosDateTime();

        $this->writeLocalHeader($relative, $nameLength, $dosTime);

        $crcHash = hash_init('crc32b');
        $size = 0;

        while (!feof($stream)) {
            if ($checker !== null && $checker()) {
                throw new InstallationCancelledException('Installation cancelled.');
            }

            $chunk = fread($stream, 262144);

            if ($chunk === false) {
                throw new RuntimeException('Unable to read a modpack file: ' . $relative);
            }

            if ($chunk === '') {
                if (feof($stream)) {
                    break;
                }
                continue;
            }

            $written = fwrite($this->output, $chunk);

            if ($written === false || $written !== strlen($chunk)) {
                throw new RuntimeException('Unable to write a modpack file into the normalized archive: ' . $relative);
            }

            hash_update($crcHash, $chunk);

            $size += strlen($chunk);

            $callback = $this->progressCallback;

            if ($callback !== null) {
                $callback($baseDone + $size, $totalBytes);
            }
        }

        if ($size > 0xFFFFFFFF) {
            throw new RuntimeException('A modpack file in the normalized archive exceeds the maximum supported size.');
        }

        $crc = unpack('N', hash_final($crcHash, true))[1];
        ...patch...
        $this->centralDirectory[] = ['name'=>..., 'crc'=>..., 'size'=>..., 'offset'=>..., 'dosTime'=>...];
    }

    public function finish(): void
    { ... }

    ...
}
