         } catch (InvalidArgumentException $exception) {
             return response()->json([
                 'error' => $exception->getMessage(),
             ], 422);
         } catch (CatalogUnavailableException $exception) {
             return response()->json([
                 'error' => $exception->getMessage(),
             ], 503);
         } catch (CatalogProviderException $exception) {
             return response()->json([
                 'error' => $exception->getMessage(),
             ], 502);
         } catch (Throwable $exception) {
