```php
public function downloadBatch(array $tasks): array
{
    $results = [];
    if ($tasks === []) {
        return $results;
    }

    $this->ensureTemporaryRoot();

    // validate task shape first
    $pending = [];
    foreach ($tasks as $task) {
        $id = $task['id'] ?? '';
        $urls = $task['urls'] ?? [];
        $destination = $task['destination'] ?? '';

        if ($id === '' || !is_array($urls) || $destination === '') {
            throw new InvalidArgumentException('A download batch task is malformed.');
        }
        if ($urls === []) { $results[$id] = null; continue; } // no sources
        // ensure parent dir
        $dir = dirname($destination);
        if (!is_dir($dir) && !@mkdir($dir, 0750, true) && !is_dir($dir)) {
            throw new RuntimeException('Unable to create the download batch directory.');
        }
        $pending[$id] = [
            'id' => $id,
            'urls' => array_values($urls),
            'index' => 0,
            'attempts' => self::MAX_ATTEMPTS,
            'hops' => 0,
            'url' => null,
            'destination' => $destination,
            'fp' => null,
            'headers' => '',
            'transferred' => 0,   // bytes carried across hops/attempts
            'active' => 0.0,      // bytes from the currently active transfer
            'done' => false,
            'size' => 0,
            'handle' => null,
        ];
        $results[$id] = null; // placeholder; replaced on success
    }

    try {
        $mh = curl_multi_init();
        if ($mh === false) {
            throw new RuntimeException('Unable to initialize the concurrent HTTP client.');
        }

        $active = [];
        // add initial handles
        foreach ($pending as $id => $state) {
            if (count($active) >= self::BATCH_CONCURRENCY) break;
            $curl = $this->batchOpenHandle($state);
            if ($curl !== null) {
                $active[$id] = true;
                curl_multi_add_handle($mh, $curl);
            }
        }

        $didRun = false;
        $lastPeak = 0;
        do {
            // cancel check each loop iteration
            $this->ensureNotCancelled();

            $exec = curl_multi_exec($mh, $running);
            while ($exec === CURLM_CALL_MULTI_PERFORM) {
                $exec = curl_multi_exec($mh, $running);
            }
            if ($exec !== CURLM_OK) {
                throw new RuntimeException('The concurrent download engine failed.');
            }

            // process messages
            $lastPeak = $this->processBatchMessages($mh, $pending, $active, $running, $lastPeak);

            // feed new handles
            if (count($active) < self::BATCH_CONCURRENCY && $running < self::BATCH_CONCURRENCY) {
                foreach ($pending as $id => $state) {
                    if (isset($active[$id]) || $state['done']) continue;
                    if (count($active) >= self::BATCH_CONCURRENCY) break;
                    $curl = $this->batchOpenHandle($state);
                    if ($curl !== null) {
                        $active[$id] = true;
                        curl_multi_add_handle($mh, $curl);
                    }
                }
            }

            // progress aggregation (throttled)
            $this->aggregateBatchProgress($pending, $lastPeak);

            if ($running > 0) {
                curl_multi_select($mh, 0.2);
            }
        } while ($running > 0);

        foreach ($pending as $id => $state) {
            if ($state['done']) $results[$id] = $state['destination'];
        }
    } finally {
        curl_multi_close($mh ?? null);
        foreach ($pending as $id => $state) {
            if (is_resource($state['fp'])) fclose($state['fp']);
            if (!$state['done'] && is_file($state['destination'])) @unlink($state['destination']);
        }
    }

    return $results;
}
