#!/usr/bin/env python3
"""
CurseForge Modpack Extractor + Downloader - v4

This version fixes a mistake in v3:
It does NOT reject API keys merely because they begin with "$2a$", "$2b$",
or "$2y$". The script must let CurseForge itself validate the key.

Usage:
    python3 curseforge_server_pack.py "Vagrant Saga Server Pack-1.1.8.zip" \
        --api-key-file ~/.curseforge_api_key

Or:
    export CURSEFORGE_API_KEY='YOUR_REAL_CURSEFORGE_API_KEY'
    python3 curseforge_server_pack.py "Vagrant Saga Server Pack-1.1.8.zip"

The API key is sent in the x-api-key header, as required by CurseForge.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import sys
import time
import zipfile
from pathlib import Path
from urllib.error import HTTPError, URLError
from urllib.parse import quote
from urllib.request import Request, urlopen

API_BASE = "https://api.curseforge.com/v1"
CDN_BASE = "https://edge.forgecdn.net/files"
USER_AGENT = "CurseForgeModpackVerifier/4.0"
CHUNK_SIZE = 1024 * 1024
BATCH_SIZE = 50


class CFError(RuntimeError):
    pass


def clean_key(value: str) -> str:
    value = value.strip()

    # Remove one accidental pair of surrounding quotes.
    # Do not modify internal characters, including '$'.
    if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
        value = value[1:-1].strip()

    return value


def get_api_key(args: argparse.Namespace) -> str | None:
    if args.api_key_file:
        try:
            return clean_key(
                Path(args.api_key_file).expanduser().read_text(
                    encoding="utf-8"
                )
            )
        except OSError as exc:
            raise CFError(f"Could not read API key file: {exc}") from exc

    if args.api_key is not None:
        return clean_key(args.api_key)

    value = os.environ.get("CURSEFORGE_API_KEY")
    return clean_key(value) if value is not None else None


def http_request(
    method: str,
    url: str,
    api_key: str,
    body: bytes | None = None,
    accept: str = "application/json",
    timeout: int = 60,
) -> tuple[int, bytes, dict[str, str]]:
    headers = {
        "Accept": accept,
        "User-Agent": USER_AGENT,
        "x-api-key": api_key,
    }

    if body is not None:
        headers["Content-Type"] = "application/json"

    request = Request(url, data=body, headers=headers, method=method)

    try:
        with urlopen(request, timeout=timeout) as response:
            return response.status, response.read(), dict(response.headers)
    except HTTPError as exc:
        raw = exc.read()
        detail = raw.decode("utf-8", errors="replace").strip()
        # Preserve the actual server response for diagnosis.
        raise CFError(
            f"HTTP {exc.code}: {detail or exc.reason}"
        ) from exc
    except (URLError, TimeoutError) as exc:
        raise CFError(f"Network error: {exc}") from exc


def json_request(
    method: str,
    url: str,
    api_key: str,
    payload: dict | None = None,
) -> dict:
    body = json.dumps(payload).encode("utf-8") if payload is not None else None
    _, raw, _ = http_request(method, url, api_key, body)

    try:
        result = json.loads(raw.decode("utf-8"))
    except json.JSONDecodeError as exc:
        raise CFError(
            f"Invalid JSON from CurseForge: {raw[:500]!r}"
        ) from exc

    if not isinstance(result, dict):
        raise CFError("Unexpected non-object JSON response from CurseForge")

    return result


def validate_api_key(api_key: str) -> None:
    """
    Test authentication with GET /v1/games/432 (Minecraft).

    Do not classify the key based on its visual format. Only CurseForge's
    response determines whether the key is accepted.
    """
    if not api_key:
        raise CFError("The API key is empty.")

    try:
        response = json_request(
            "GET",
            f"{API_BASE}/games/432",
            api_key,
        )
    except CFError as exc:
        raise CFError(
            "CurseForge API authentication test failed.\n"
            f"  {exc}\n\n"
            "The script sent the key as the x-api-key HTTP header. "
            "If this is a real CurseForge key and it still returns 403, "
            "the key may not have access to the public Core API, or "
            "CurseForge may be rejecting requests from this environment. "
            "The exact server response above is important."
        ) from exc

    if not response.get("data"):
        raise CFError(
            "CurseForge returned success but no Minecraft game data."
        )

    print("    API authentication: OK")


def safe_extract(zip_path: Path, destination: Path) -> None:
    destination = destination.resolve()

    with zipfile.ZipFile(zip_path, "r") as archive:
        for member in archive.infolist():
            target = (destination / member.filename).resolve()
            if target != destination and destination not in target.parents:
                raise CFError(
                    f"Unsafe ZIP path detected: {member.filename}"
                )
        archive.extractall(destination)


def safe_filename(name: str) -> str:
    name = name.replace("\\", "/").split("/")[-1]
    name = re.sub(r"[\x00-\x1f]", "_", name).strip()

    if not name or name in {".", ".."}:
        raise CFError("CurseForge returned an invalid filename.")

    return name


def format_size(value: int) -> str:
    number = float(value)
    for unit in ("B", "KB", "MB", "GB", "TB"):
        if number < 1024 or unit == "TB":
            return f"{number:.1f} {unit}"
        number /= 1024
    return f"{value} B"


def sha1_file(path: Path) -> str:
    digest = hashlib.sha1()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(CHUNK_SIZE), b""):
            digest.update(chunk)
    return digest.hexdigest()


def fetch_metadata(file_ids: list[int], api_key: str) -> dict[int, dict]:
    metadata: dict[int, dict] = {}

    for start in range(0, len(file_ids), BATCH_SIZE):
        batch = file_ids[start:start + BATCH_SIZE]
        payload = json_request(
            "POST",
            f"{API_BASE}/mods/files",
            api_key,
            {"fileIds": batch},
        )

        items = payload.get("data")
        if not isinstance(items, list):
            raise CFError(
                "Unexpected response from POST /v1/mods/files."
            )

        for item in items:
            if isinstance(item, dict):
                try:
                    metadata[int(item["id"])] = item
                except (KeyError, TypeError, ValueError):
                    pass

        if start + BATCH_SIZE < len(file_ids):
            time.sleep(0.15)

    return metadata


def make_cdn_url(file_id: int, filename: str) -> str:
    return (
        f"{CDN_BASE}/{file_id // 1000}/{file_id % 1000}/"
        f"{quote(filename, safe='-_.()[]+')}"
    )


def make_website_url(project_id: int, file_id: int) -> str:
    return (
        "https://www.curseforge.com/minecraft/mc-mods/"
        f"{project_id}/files/{file_id}/download"
    )


def candidate_urls(
    project_id: int,
    file_id: int,
    metadata: dict | None,
    api_key: str,
) -> list[tuple[str, str]]:
    candidates: list[tuple[str, str]] = []

    # Candidate 1: official API resolver.
    try:
        payload = json_request(
            "GET",
            f"{API_BASE}/mods/{project_id}/files/{file_id}/download-url",
            api_key,
        )
        url = payload.get("data")
        if isinstance(url, str) and url:
            candidates.append(("API download URL", url))
    except CFError:
        pass

    if metadata:
        direct_url = metadata.get("downloadUrl")
        if isinstance(direct_url, str) and direct_url:
            candidates.append(("metadata download URL", direct_url))

        raw_name = metadata.get("fileName")
        if isinstance(raw_name, str) and raw_name:
            filename = safe_filename(raw_name)
            candidates.append(
                ("CurseForge CDN", make_cdn_url(file_id, filename))
            )

    candidates.append(
        (
            "CurseForge website redirect",
            make_website_url(project_id, file_id),
        )
    )

    unique: list[tuple[str, str]] = []
    seen: set[str] = set()
    for method, url in candidates:
        if url not in seen:
            seen.add(url)
            unique.append((method, url))
    return unique


def download_file(
    url: str,
    destination: Path,
    api_key: str,
    overwrite: bool,
) -> tuple[int, str]:
    if destination.exists() and not overwrite:
        return destination.stat().st_size, url

    destination.parent.mkdir(parents=True, exist_ok=True)
    partial = destination.with_name(destination.name + ".part")

    request = Request(
        url,
        headers={
            "Accept": "*/*",
            "User-Agent": USER_AGENT,
            "x-api-key": api_key,
        },
    )

    try:
        with urlopen(request, timeout=180) as response:
            content_type = (
                response.headers.get("Content-Type") or ""
            ).lower()

            if "text/html" in content_type:
                raise CFError(
                    "Received HTML instead of a downloadable file."
                )

            total = 0
            with partial.open("wb") as output:
                while True:
                    chunk = response.read(CHUNK_SIZE)
                    if not chunk:
                        break
                    output.write(chunk)
                    total += len(chunk)

            if total == 0:
                raise CFError("Downloaded file is empty.")

            final_url = response.geturl()
            partial.replace(destination)
            return total, final_url

    except Exception:
        partial.unlink(missing_ok=True)
        raise


def main() -> int:
    parser = argparse.ArgumentParser(
        description=(
            "Extract a CurseForge modpack and download its manifest files."
        )
    )
    parser.add_argument("zip_file", help="Path to the CurseForge ZIP")
    parser.add_argument("--api-key", help="CurseForge API key")
    parser.add_argument(
        "--api-key-file",
        help="Read the API key literally from a file",
    )
    parser.add_argument(
        "--output",
        help="Output directory; defaults to <zip-name>-extracted",
    )
    parser.add_argument(
        "--overwrite",
        action="store_true",
        help="Re-download files that already exist",
    )
    parser.add_argument(
        "--delay",
        type=float,
        default=0.25,
        help="Delay between downloads in seconds",
    )
    args = parser.parse_args()

    if args.api_key and args.api_key_file:
        print("ERROR: Use only one of --api-key and --api-key-file.")
        return 1

    zip_path = Path(args.zip_file).expanduser().resolve()
    if not zip_path.is_file():
        print(f"ERROR: ZIP file not found: {zip_path}", file=sys.stderr)
        return 1

    try:
        api_key = get_api_key(args)
    except CFError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1

    if not api_key:
        print(
            "ERROR: No API key supplied.\n\n"
            "Recommended setup:\n"
            "  printf '%s' 'YOUR_REAL_API_KEY' > ~/.curseforge_api_key\n"
            "  chmod 600 ~/.curseforge_api_key\n"
            "  python3 curseforge_server_pack.py "
            f"'{zip_path.name}' --api-key-file ~/.curseforge_api_key\n\n"
            "Or:\n"
            "  export CURSEFORGE_API_KEY='YOUR_REAL_API_KEY'",
            file=sys.stderr,
        )
        return 1

    output_dir = (
        Path(args.output).expanduser().resolve()
        if args.output
        else zip_path.parent / f"{zip_path.stem}-extracted"
    )
    output_dir.mkdir(parents=True, exist_ok=True)

    print(f"[1/4] Extracting: {zip_path.name}")
    try:
        safe_extract(zip_path, output_dir)
    except (OSError, zipfile.BadZipFile, CFError) as exc:
        print(f"ERROR: Extraction failed: {exc}", file=sys.stderr)
        return 1

    manifest_path = output_dir / "manifest.json"
    if not manifest_path.is_file():
        print("ERROR: manifest.json not found.", file=sys.stderr)
        return 1

    try:
        manifest = json.loads(
            manifest_path.read_text(encoding="utf-8")
        )
    except (OSError, json.JSONDecodeError) as exc:
        print(f"ERROR: Could not read manifest.json: {exc}", file=sys.stderr)
        return 1

    entries = manifest.get("files")
    if not isinstance(entries, list):
        print("ERROR: manifest.json has no valid files list.")
        return 1

    minecraft = manifest.get("minecraft") or {}
    loaders = ", ".join(
        str(item.get("id", "unknown"))
        for item in minecraft.get("modLoaders", [])
        if isinstance(item, dict)
    ) or "unknown"

    print(f"    Pack: {manifest.get('name', zip_path.stem)}")
    print(f"    Minecraft: {minecraft.get('version', 'unknown')}")
    print(f"    Loader: {loaders}")
    print(f"    Manifest entries: {len(entries)}")

    print("[2/4] Validating CurseForge API access...")
    try:
        validate_api_key(api_key)
    except CFError as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        return 1

    valid: list[tuple[int, int, bool]] = []
    for index, entry in enumerate(entries, 1):
        if not isinstance(entry, dict):
            print(f"  [{index}/{len(entries)}] INVALID entry")
            continue

        try:
            project_id = int(entry["projectID"])
            file_id = int(entry["fileID"])
        except (KeyError, TypeError, ValueError):
            print(f"  [{index}/{len(entries)}] INVALID projectID/fileID")
            continue

        valid.append(
            (project_id, file_id, bool(entry.get("required", True)))
        )

    print("[3/4] Fetching CurseForge file metadata...")
    try:
        file_ids = list(dict.fromkeys(file_id for _, file_id, _ in valid))
        metadata_by_id = fetch_metadata(file_ids, api_key)
    except CFError as exc:
        print(f"ERROR: Could not fetch file metadata: {exc}", file=sys.stderr)
        return 1

    print(
        f"    Metadata received: "
        f"{len(metadata_by_id)}/{len(file_ids)} files"
    )

    mods_dir = output_dir / "mods"
    mods_dir.mkdir(parents=True, exist_ok=True)

    downloaded = 0
    skipped = 0
    failed = 0
    total_bytes = 0
    failures: list[str] = []

    print("[4/4] Downloading manifest files...")

    for index, (project_id, file_id, required) in enumerate(valid, 1):
        metadata = metadata_by_id.get(file_id)

        filename = None
        if metadata:
            raw_name = metadata.get("fileName")
            if isinstance(raw_name, str) and raw_name:
                filename = safe_filename(raw_name)
        filename = filename or f"{file_id}.jar"

        destination = mods_dir / filename

        if destination.exists() and not args.overwrite:
            skipped += 1
            print(f"  [{index}/{len(valid)}] SKIP {filename} (exists)")
            continue

        success = False
        errors: list[str] = []

        for method, url in candidate_urls(
            project_id, file_id, metadata, api_key
        ):
            try:
                print(
                    f"  [{index}/{len(valid)}] "
                    f"{filename} via {method}"
                )

                size, final_url = download_file(
                    url, destination, api_key, args.overwrite
                )

                expected_sha1 = None
                if metadata:
                    for item in metadata.get("hashes", []):
                        if (
                            isinstance(item, dict)
                            and item.get("algo") == 1
                        ):
                            expected_sha1 = str(
                                item.get("value", "")
                            ).lower()
                            break

                if expected_sha1:
                    actual_sha1 = sha1_file(destination)
                    if actual_sha1 != expected_sha1:
                        destination.unlink(missing_ok=True)
                        raise CFError(
                            "SHA-1 mismatch: "
                            f"expected {expected_sha1}, "
                            f"received {actual_sha1}"
                        )

                downloaded += 1
                total_bytes += size
                success = True
                print(f"       OK {format_size(size)}")
                break

            except (CFError, HTTPError, URLError, OSError, ValueError) as exc:
                errors.append(f"{method}: {exc}")

        if not success:
            failed += 1
            message = (
                f"fileID={file_id}, projectID={project_id}, "
                f"required={required}: " + " | ".join(errors)
            )
            failures.append(message)
            print(f"       FAIL {message}", file=sys.stderr)

        time.sleep(max(0.0, args.delay))

    print("\nFinished")
    print(f"    Output: {output_dir}")
    print(f"    Downloaded: {downloaded}")
    print(f"    Skipped: {skipped}")
    print(f"    Failed: {failed}")
    print(f"    Downloaded size: {format_size(total_bytes)}")

    if failures:
        report = output_dir / "curseforge-download-failures.txt"
        report.write_text("\n".join(failures) + "\n", encoding="utf-8")
        print(f"    Failure report: {report}")

    return 1 if failed else 0


if __name__ == "__main__":
    raise SystemExit(main())

